public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {

    // Check if the file exists and is readable
    if (!file.exists() || !file.canRead()) {
        throw new FileNotFoundException("File not found or not readable: " + file.getAbsolutePath());
    }

    // Check if the time ranges are valid
    if (timeRanges == null || timeRanges.isEmpty()) {
        throw new IllegalArgumentException("Time ranges must be provided");
    }

    // Parse the file and extract the thread snapshots
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            // Check if the line contains a thread snapshot
            if (line.startsWith("ThreadSnapshot")) {
                // Extract the thread snapshot data
                String[] parts = line.split("\\|");
                String threadName = parts[1];
                long threadId = Long.parseLong(parts[2]);
                long startTime = Long.parseLong(parts[3]);
                long endTime = Long.parseLong(parts[4]);
                String state = parts[5];
                String stackTrace = parts[6];

                // Check if the thread snapshot is within the time range
                boolean isInRange = false;
                for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
                    if (startTime >= timeRange.getStartTime() && endTime <= timeRange.getEndTime()) {
                        isInRange = true;
                        break;
                    }
                }

                // Add the thread snapshot to the list if it is within the time range
                if (isInRange) {
                    threadSnapshots.add(new ThreadSnapshot(threadName, threadId, startTime, endTime, state, stackTrace));
                }
            }
        }
    }

    return threadSnapshots;
}
